/* ================= v6 compact pass: denser, higher contrast, no sideways scrolling ================= */
.soa { --mut:#475163; --line:rgba(30,45,70,.14); --gap:10px; padding:14px; min-height:0; }
.soa.soa-dark { --mut:#b4bdcc; }
.soa-top { margin-bottom:10px; }
