.soa-kpis { margin-bottom:10px; }
.soa-kpi { display:grid; grid-template-columns:32px minmax(0,1fr) auto; grid-template-areas:"i l v" "i s v"; align-items:center; column-gap:10px; padding:10px 14px; text-align:start; }
.soa-kpi-i { grid-area:i; margin:0; width:32px; height:32px; }
.soa-kpi-l { grid-area:l; font-size:12px; font-weight:600; color:var(--fg); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.soa-kpi-s { grid-area:s; font-size:11px; min-height:0; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.soa-kpi-v { grid-area:v; font-size:24px; line-height:1; }
/* cards + headers */
.soa-card-h { padding:10px 14px 6px; }
.soa-card-t { font-size:14px; }
.soa-tools { padding:0 14px 8px; }
/* tables: wrap instead of scrolling sideways; sticky header kept */
.soa-scroll { overflow-x:hidden; overflow-y:auto; max-height:70vh; }
.soa-t { table-layout:auto; }
.soa-t th { padding:7px 10px; background:#dfe3ec; color:#2c3646; font-weight:650; font-size:11.5px; white-space:normal; }
.soa-t td { padding:7px 10px; overflow-wrap:anywhere; }
.soa-t .nw { white-space:normal; }
.soa-t td.n, .soa-t th.n { white-space:nowrap; }
.soa-t tbody tr:nth-child(even) { background:rgba(40,60,100,.025); }
.soa-t td.lead b { font-size:12.5px; }
/* hide secondary columns on medium widths, they come back in the stacked (card) view */
@container (min-width:901px) and (max-width:1180px) { .soa-t .c-opt { display:none; } }
/* stacked card view starts earlier (≤900px) so nothing ever scrolls sideways */
@container (max-width:900px) {
  .soa-scroll { max-height:none; overflow:visible; }
  .soa-stack thead { display:none; }
  .soa-stack, .soa-stack tbody, .soa-stack tr { display:block; }
  .soa-stack tr { margin:0 10px 8px; padding:8px 12px; border-radius:12px; background:var(--glass-hi); border:1px solid var(--line); }
  .soa-stack tbody tr:nth-child(even) { background:var(--glass-hi); }
  .soa-stack td { display:grid; grid-template-columns:minmax(80px,30%) minmax(0,1fr); gap:10px; align-items:start; padding:3px 0; border:0; text-align:start; white-space:normal; }
  .soa-stack td::before { content:attr(data-l); font-size:11.5px; color:var(--mut); padding-top:1px; }
  .soa-stack td.n > div { text-align:start; }
  .soa-stack td.lead { display:block; padding:0 0 6px; margin-bottom:4px; border-bottom:1px solid var(--line); }
  .soa-stack td.lead::before { content:none; }
  .soa-stack td[data-l=""] { display:block; padding-top:6px; } .soa-stack td[data-l=""]::before { content:none; }
}
/* review queue: compact cards with a status edge */
.soa-queue { gap:10px; }
.soa-qc { border-inline-start:4px solid var(--line); }
.soa-qc.ok { border-inline-start-color:#1f8a5b; } .soa-qc.warn { border-inline-start-color:#d08a17; } .soa-qc.bad { border-inline-start-color:#c2412f; }
.soa-q-h { padding:10px 14px 2px; align-items:flex-start; }
.soa-q-h h3 { font-size:14px; }
.soa-q-h .soa-c-m { white-space:normal; }
.soa-q-st { display:flex; align-items:center; gap:8px; }
.soa-q-st .soa-card-s { margin:0; }
.soa-q-meta { padding:2px 14px 6px; gap:4px 12px; font-size:11.5px; }
.soa-trio { padding:0 14px 6px; gap:6px; }
.soa-trio > div { padding:6px 10px; border-radius:10px; }
.soa-trio small { font-size:11px; }
.soa-trio b { font-size:14px; }
.soa-trio > div.bad { background:var(--red-bg); color:var(--red); }
.soa-why, .soa-note, .soa-err, .soa-q-ok, .soa-q-ag { margin:0 14px 6px; }
.soa-why li { padding:6px 12px; font-size:12px; }
.soa-why-h { padding:6px 12px; }
.soa-q-ok { padding:7px 10px; font-size:12px; }
.soa-q-files { padding:0 14px 6px; }
.soa-q-act { padding:4px 14px 12px; grid-template-columns:minmax(0,1fr) auto; align-items:center; gap:8px; }
.soa-q-act .soa-ta { min-height:0; height:32px; padding:6px 10px; resize:none; font-size:12.5px; }
.soa-q-act .soa-ta:focus { height:64px; }
.soa-q-btns { flex-wrap:nowrap; }
.soa-mini th, .soa-mini td { padding:5px 10px; }
/* sales: denser customer list and form */
.soa-c { padding:8px 10px; }
.soa-step { padding:10px 14px 2px; }
.soa-opts { grid-template-columns:repeat(auto-fit,minmax(170px,1fr)); gap:6px; }
.soa-opt { padding:9px 10px; gap:1px; border-radius:12px; }
.soa-opt svg { width:17px; height:17px; margin-bottom:2px; }
.soa-act { padding:10px 14px 14px; }
/* collections */
.soa-cl-h { padding:10px 14px; gap:8px 18px; }
.soa-cstats .soa-card, .soa-csum .soa-card { padding:9px 12px; }
.soa-cstats b, .soa-csum b { font-size:19px; }
.soa-cbar { padding:9px 14px; }
.soa-cc { padding:12px 14px; gap:8px; }
.soa-cc-amt > div { padding:8px 10px; }
@container (max-width:640px) {
  .soa { padding:8px; }
  .soa-kpi { padding:8px 10px; column-gap:8px; grid-template-columns:28px minmax(0,1fr) auto; }
  .soa-kpi-i { width:28px; height:28px; } .soa-kpi-i svg { width:14px; height:14px; }
  .soa-kpi-v { font-size:20px; }
  .soa-q-act { grid-template-columns:1fr; }
  .soa-q-btns .soa-btn.sm { height:36px; }
  .soa-q-h, .soa-q-meta, .soa-trio, .soa-q-act, .soa-q-files { padding-inline:12px; }
  .soa-why, .soa-note, .soa-err, .soa-q-ok, .soa-q-ag { margin-inline:12px; }
}
@container (max-width:420px) {
  .soa-kpis { grid-template-columns:1fr 1fr; }
  .soa-kpi { grid-template-columns:minmax(0,1fr) auto; grid-template-areas:"l v" "s v"; }
  .soa-kpi-i { display:none; }
  .soa-trio b { font-size:13px; }
}
.soa-addcol { display:flex; flex-wrap:wrap; gap:8px; padding:0 14px 10px; }
.soa-addcol .soa-sel { flex:1 1 240px; max-width:420px; }
.soa-assign-top { display:flex; justify-content:space-between; align-items:flex-start; gap:8px; }
.soa-assign-top span { display:grid; min-width:0; } .soa-assign-top small { color:var(--mut); font-size:11.5px; overflow-wrap:anywhere; }
.soa-assign-c > .soa-assign-top { display:flex; }
@container (max-width:460px) {
  .soa-mini { font-size:10.5px; table-layout:fixed; }
  .soa-mini th, .soa-mini td { padding:4px 3px; white-space:normal; overflow-wrap:anywhere; }
  .soa-mini th:first-child { width:26%; padding-inline-start:8px; }
  .soa-mini td:last-child { padding-inline-end:8px; }
  .soa-mini-w { overflow:visible; }
}
.soa-q-act .soa-ta { width:100%; box-sizing:border-box; }
@container (max-width:640px) {
  .soa-q-btns { display:grid; grid-template-columns:1fr 1fr 1.5fr; gap:6px; }
  .soa-q-btns .soa-btn { padding:0 8px; min-width:0; justify-content:center; }
}
@container (max-width:420px) {
  .soa-kpi-l, .soa-kpi-s { white-space:normal; overflow:visible; }
  .soa-kpi-v { font-size:18px; }
}
.soa-act { align-items:center; }
.soa-left { margin-inline-end:auto; font-size:12px; font-weight:600; color:var(--mut); }
.soa-left.none { color:var(--red); }
.soa-mailed { display:inline-flex; align-items:center; gap:5px; font-size:12px; font-weight:600; color:var(--green); }
.soa-mailed svg { width:13px; height:13px; }
@container (max-width:640px) { .soa-left { width:100%; text-align:center; } }
.soa-t .soa-ag-b { grid-template-columns:repeat(2,minmax(0,1fr)); }
.soa-ag-b small { white-space:normal; }
.soa-agl { display:grid; gap:1px; min-width:120px; }
.soa-agl > div b { font-size:13.5px; font-variant-numeric:tabular-nums; }
.soa-agl span { display:flex; justify-content:space-between; gap:10px; font-size:11.5px; }
.soa-agl span b { font-weight:600; font-variant-numeric:tabular-nums; }
.soa.soa-rtl .soa-agl b { direction:ltr; unicode-bidi:isolate; }
.soa-assign-f { display:flex; align-items:flex-end; gap:8px; flex-wrap:wrap; }
.soa-assign-f label { display:grid; gap:3px; font-size:11.5px; font-weight:600; color:var(--mut); flex:1 1 120px; }
.soa-assign-f .soa-in { width:100%; height:32px; }
.soa-skip { color:var(--amber); font-weight:600; }
.soa-assign-c > div.soa-assign-top:first-child { display:flex; }
.finance-dashboard { display:grid; gap:18px; }
.finance-dashboard .soa-top h2 { margin:0; font-size:20px; color:inherit; }
.finance-dashboard .soa-tabs { flex-wrap:wrap; gap:10px; }
.finance-fields { display:flex; flex-wrap:wrap; gap:18px; margin:18px 0; }
.finance-dashboard label { display:grid; gap:6px; flex:1 1 220px; }
.finance-dashboard .soa-btn { min-height:44px; }
.finance-dashboard .soa-in,.finance-dashboard .soa-sel { width:100%; min-height:44px; }
.finance-request { border-top:1px solid var(--line); padding:16px 0; }
